import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.cZsgxozV.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/github-release-body.md","filePath":"desktop/github-release-body.md"}`),a={name:`desktop/github-release-body.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<p>Unified release (macOS DMG / Windows NSIS / Android APK) with auto-update manifest.</p><ul><li>macOS: universal DMG</li><li>Windows: NSIS installer (<code>.exe</code>)</li><li>Android: sideload APKs signed with the shared DocuHaim sideload keystore — <strong>prefer the matching ABI</strong>; <code>universal</code> includes all ABIs (larger)</li><li><code>latest.json</code> + signatures for the Tauri updater (when <code>TAURI_SIGNING_PRIVATE_KEY</code> is configured)</li></ul><p>Install / update endpoint: <a href="https://github.com/explainpark101/DocuHaim/releases/latest" target="_blank" rel="noreferrer">https://github.com/explainpark101/DocuHaim/releases/latest</a></p><p>Unsigned desktop builds if signing secrets are not configured — see docs/desktop/code-signing.md.</p><h2 id="android-apk-—-which-file-to-download" tabindex="-1">Android APK — which file to download <a class="header-anchor" href="#android-apk-—-which-file-to-download" aria-label="Permalink to “Android APK — which file to download”">​</a></h2><table tabindex="0"><thead><tr><th>Asset name pattern</th><th>ABI</th><th>Typical devices</th></tr></thead><tbody><tr><td><code>DocuHaim_*_arm64-v8a-debug.apk</code></td><td><code>arm64-v8a</code></td><td>Most phones / tablets (recommended)</td></tr><tr><td><code>DocuHaim_*_armeabi-v7a-debug.apk</code></td><td><code>armeabi-v7a</code></td><td>Older 32-bit ARM devices</td></tr><tr><td><code>DocuHaim_*_x86_64-debug.apk</code></td><td><code>x86_64</code></td><td>Many Android emulators</td></tr><tr><td><code>DocuHaim_*_x86-debug.apk</code></td><td><code>x86</code></td><td>Older x86 emulators</td></tr><tr><td><code>DocuHaim_*_universal-debug.apk</code></td><td>all of the above</td><td>Any device (largest download)</td></tr></tbody></table><h3 id="how-to-check-your-device-architecture" tabindex="-1">How to check your device architecture <a class="header-anchor" href="#how-to-check-your-device-architecture" aria-label="Permalink to “How to check your device architecture”">​</a></h3><p><strong>On the phone (no PC)</strong></p><ol><li>Open <strong>Settings → About phone</strong> (or <strong>About device</strong>).</li><li>Look for <strong>CPU</strong> / <strong>Hardware</strong> / <strong>Processor</strong>, or install a free app such as <strong>CPU-Z</strong> and check <strong>SoC → ABI</strong> / <strong>Instruction Sets</strong>.</li><li>If you see <code>arm64-v8a</code> (or <code>aarch64</code>), download the <strong>arm64-v8a</strong> APK.</li></ol><p><strong>With a USB cable + <code>adb</code> (developer options enabled)</strong></p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> getprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ro.product.cpu.abi</span></span></code></pre></div><p>Example outputs:</p><ul><li><code>arm64-v8a</code> → download <code>*_arm64-v8a-debug.apk</code></li><li><code>armeabi-v7a</code> → download <code>*_armeabi-v7a-debug.apk</code></li><li><code>x86_64</code> → download <code>*_x86_64-debug.apk</code></li></ul><p>If unsure, use the <strong>universal</strong> APK.</p><p>Sideload: allow “Install unknown apps”, then open the <code>.apk</code>.<br> If an older install was signed with a different debug key, uninstall once before installing this build (otherwise Android reports a package conflict).<br> In-app updates require the same sideload certificate — see android-sideload.md.<br> Docs: <a href="https://github.com/explainpark101/DocuHaim/blob/main/docs/desktop/android-sideload.md" target="_blank" rel="noreferrer">android-sideload.md</a> · <a href="https://github.com/explainpark101/DocuHaim/blob/main/docs/desktop/code-signing.md" target="_blank" rel="noreferrer">code-signing.md</a></p>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};